import java.util.*;

/** B07 public F10 fields and exact source clocks; no valuation or identity guessing. */
final class StockProfileModel {
 static final String SCHEMA="native-stock-company-profile/v1",BASE="https://emweb.securities.eastmoney.com/PC_HSF10";
 static final String[] KINDS={"CompanySurvey","CoreConception","BusinessAnalysis"};
 static final long TTL=30L*24*60*60*1000;static final int LIMIT=1024*1024;
 static void need(boolean b,String why){StockResearchModel.need(b,why);}
 static JSONObject copy(JSONObject p)throws Exception{return new JSONObject(p.toString());}
 static Instant stamp(String at){need(at!=null&&at.matches("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$"),"资料时刻缺时区或格式无效");return OffsetDateTime.parse(at).toInstant();}
 static boolean supported(String id){StockResearchModel.identity(id);return id.split(":")[1].equals("stock");}
 static JSONObject request(String id,String kind)throws Exception{need(supported(id)&&Arrays.asList(KINDS).contains(kind),"该完整证券类型不支持F10或来源无效");String[] p=id.split(":");return new JSONObject().put("id",id).put("kind",kind).put("url",BASE+"/"+kind+"/PageAjax?code="+p[0]+p[2]);}
 static String[] arrays(String kind){return kind.equals("CompanySurvey")?new String[]{"jbzl"}:kind.equals("CoreConception")?new String[]{"ssbk","hxtc"}:new String[]{"zygcfx","jyps","zyfw"};}
 static void sourceIdentity(String id,JSONObject row)throws Exception{String[] p=id.split(":");for(String key:new String[]{"SECURITY_CODE","SECUCODE"}){if(!row.has(key)||row.isNull(key)||row.optString(key).trim().isEmpty())continue;need(row.opt(key) instanceof String,"来源证券身份类型不可核对");String value=row.getString(key).trim().toUpperCase(Locale.ROOT);if(value.matches("[0-9]{6}"))need(value.equals(p[2]),"来源代码与请求不符");else if(value.matches("[0-9]{6}\\.(SH|SZ|BJ)"))need(value.equals(p[2]+"."+p[0]),"来源完整市场身份与请求不符");else if(value.matches("(SH|SZ|BJ)[0-9]{6}"))need(value.equals(p[0]+p[2]),"来源完整市场身份与请求不符");else need(false,"来源证券身份格式不可核对");}}
 static boolean body(String id,String kind,JSONObject data)throws Exception{need(data.toString().getBytes(StandardCharsets.UTF_8).length<=LIMIT,"单个F10原字段超过1MiB，未截断");need(!Boolean.FALSE.equals(data.opt("success"))&&!Boolean.FALSE.equals(data.opt("Success")),"来源明确返回失败");boolean found=false,valuesPresent=false;for(String key:arrays(kind)){if(!data.has(key))continue;need(data.opt(key) instanceof JSONArray,"来源数组结构变化");found=true;JSONArray values=data.getJSONArray(key);valuesPresent|=values.length()>0;for(int i=0;i<values.length();i++){need(values.opt(i) instanceof JSONObject,"来源原数组项必须为对象");sourceIdentity(id,values.getJSONObject(i));}}need(found,"来源缺少原协议数组");return valuesPresent;}
 static JSONObject blank(String id,String kind)throws Exception{return new JSONObject().put("kind",kind).put("url",supported(id)?request(id,kind).getString("url"):JSONObject.NULL).put("status",supported(id)?"unavailable":"unsupported").put("data",JSONObject.NULL).put("fetchedAt",JSONObject.NULL).put("lastAttemptAt",JSONObject.NULL).put("error",JSONObject.NULL).put("cached",false).put("stale",JSONObject.NULL).put("origin",JSONObject.NULL);}
 static Object text(JSONObject o,String key){Object v=o.opt(key);return v instanceof String&&!((String)v).trim().isEmpty()?v:JSONObject.NULL;}
 static Object excerpt(Object value,int max){if(value==JSONObject.NULL)return value;String s=((String)value).replaceAll("\\s+"," ").trim();return s.length()>max?s.substring(0,max)+"...":s;}
 static Double number(Object value){if(value==null||value==JSONObject.NULL||value instanceof Boolean)return null;try{String s=String.valueOf(value).trim();if(s.isEmpty())return null;double d=Double.parseDouble(s);return Double.isFinite(d)?d:null;}catch(Exception e){return null;}}
 static double rank(JSONObject o,String key,double fallback){Double d=number(o.opt(key));return d==null?fallback:d;}
 static JSONArray rows(JSONObject data,String key){return data==null||data.optJSONArray(key)==null?new JSONArray():data.optJSONArray(key);}
 static JSONObject first(JSONObject data,String key){return rows(data,key).optJSONObject(0)==null?new JSONObject():rows(data,key).optJSONObject(0);}
 static void unique(JSONArray out,Set<String> seen,Object v,int max){if(v instanceof String&&!((String)v).isEmpty()&&seen.add((String)v)&&out.length()<max)out.put(v);}
 static JSONObject derive(String id,JSONObject sources)throws Exception{
  JSONObject survey=sources.getJSONObject(KINDS[0]).optJSONObject("data"),core=sources.getJSONObject(KINDS[1]).optJSONObject("data"),business=sources.getJSONObject(KINDS[2]).optJSONObject("data"),base=first(survey,"jbzl");
  Object industry=text(base,"EM2016");if(industry==JSONObject.NULL)industry=text(base,"INDUSTRYCSRC1");Object csrc=text(base,"INDUSTRYCSRC1");
  List<JSONObject> boardRows=new ArrayList<>();JSONArray original=rows(core,"ssbk");for(int i=0;i<original.length();i++)boardRows.add(original.getJSONObject(i));boardRows.sort(Comparator.comparingDouble(o->rank(o,"BOARD_RANK",999)));
  JSONArray boards=new JSONArray();Set<String> seen=new HashSet<>();for(JSONObject row:boardRows)unique(boards,seen,text(row,"BOARD_NAME"),24);
  List<JSONObject> mainRows=new ArrayList<>();original=rows(business,"zygcfx");String latest="";for(int i=0;i<original.length();i++){Object date=text(original.getJSONObject(i),"REPORT_DATE");if(date instanceof String&&((String)date).compareTo(latest)>0)latest=(String)date;}for(int i=0;i<original.length();i++){JSONObject row=original.getJSONObject(i);if(latest.isEmpty()||latest.equals(row.optString("REPORT_DATE")))mainRows.add(row);}mainRows.sort(Comparator.comparingDouble(o->rank(o,"RANK",99)));
  JSONArray items=new JSONArray();seen.clear();for(JSONObject row:mainRows){Object name=text(row,"ITEM_NAME");if(!(name instanceof String)||!seen.add((String)name)||items.length()>=6)continue;Double ratio=number(row.opt("MBI_RATIO"));Object percent=JSONObject.NULL;if(ratio!=null){double rounded=Math.copySign(Math.floor(Math.abs(ratio*10000)+0.5)/100,ratio);if(Double.isFinite(rounded))percent=rounded;}items.put(new JSONObject().put("name",name).put("ratio",percent).put("reportDate",text(row,"REPORT_DATE")));}
  Object scope=text(first(business,"zyfw"),"BUSINESS_SCOPE"),summary=text(first(business,"jyps"),"BUSINESS_REVIEW");if(summary==JSONObject.NULL)summary=scope;if(summary==JSONObject.NULL){original=rows(core,"hxtc");for(int i=0;i<original.length();i++){JSONObject r=original.getJSONObject(i);if("经营范围".equals(r.optString("KEYWORD"))||"经营范围".equals(r.optString("KEY_CLASSIF"))){summary=text(r,"MAINPOINT_CONTENT");break;}}}
  JSONArray tags=new JSONArray();seen.clear();unique(tags,seen,industry,16);unique(tags,seen,csrc,16);for(int i=0;i<Math.min(8,boards.length());i++)unique(tags,seen,boards.get(i),16);for(int i=0;i<Math.min(3,items.length());i++)unique(tags,seen,items.getJSONObject(i).get("name"),16);
  Object fetched=JSONObject.NULL,attempt=JSONObject.NULL;Instant fetchedMs=null,attemptMs=null;boolean cached=false,degraded=false;for(String kind:KINDS){JSONObject s=sources.getJSONObject(kind);cached|=s.getBoolean("cached");degraded|=Arrays.asList("failed","unavailable","unsupported","cached-after-failure").contains(s.getString("status"));if(!s.isNull("fetchedAt")&&(fetchedMs==null||stamp(s.getString("fetchedAt")).isAfter(fetchedMs))){fetchedMs=stamp(s.getString("fetchedAt"));fetched=s.get("fetchedAt");}if(!s.isNull("lastAttemptAt")&&(attemptMs==null||stamp(s.getString("lastAttemptAt")).isAfter(attemptMs))){attemptMs=stamp(s.getString("lastAttemptAt"));attempt=s.get("lastAttemptAt");}}
  String[] p=id.split(":");return new JSONObject().put("schema",SCHEMA).put("id",id).put("source","Eastmoney F10").put("sourceUrl",supported(id)?BASE+"/CompanySurvey/Index?code="+p[0]+p[2]+"&type=web":JSONObject.NULL).put("name",text(base,"SECURITY_NAME_ABBR")).put("companyName",text(base,"ORG_NAME")).put("securityType",text(base,"SECURITY_TYPE")).put("exchange",text(base,"TRADE_MARKET")).put("industry",industry).put("csrcIndustry",csrc).put("boards",boards).put("mainBusinessItems",items).put("businessScope",excerpt(scope,320)).put("businessSummary",excerpt(summary,220)).put("tags",tags).put("fetchedAt",fetched).put("lastAttemptAt",attempt).put("cached",cached).put("degraded",degraded).put("sources",sources);
 }
 static void validate(String id,JSONObject p)throws Exception{
  StockResearchModel.identity(id);need(SCHEMA.equals(p.optString("schema"))&&id.equals(p.optString("id")),"主营缓存与完整身份/版本不符");need(p.toString().getBytes(StandardCharsets.UTF_8).length<=8*LIMIT,"主营完整资料超过8MiB");JSONObject sources=p.getJSONObject("sources");need(sources.length()==3,"主营来源不完整");
  for(String kind:KINDS){JSONObject s=sources.getJSONObject(kind),empty=blank(id,kind);need(s.length()==empty.length()&&kind.equals(s.optString("kind"))&&StockResearchModel.canonical(s.get("url")).equals(StockResearchModel.canonical(empty.get("url"))),"主营来源字段或URL变化");for(Iterator<String> it=s.keys();it.hasNext();)need(empty.has(it.next()),"主营来源含未知状态字段");need(s.opt("cached") instanceof Boolean&&(s.isNull("stale")||s.opt("stale") instanceof Boolean),"主营缓存状态类型错误");String status=s.getString("status");need(Arrays.asList("ready","empty","unavailable","unsupported","failed","cached-after-failure").contains(status),"主营来源状态无效");if(!s.isNull("lastAttemptAt"))stamp(s.getString("lastAttemptAt"));
   if(!s.isNull("data")){need(supported(id)&&s.opt("data") instanceof JSONObject,"该类型不支持公司资料");boolean has=body(id,kind,s.getJSONObject("data"));need(!s.isNull("fetchedAt")&&!s.isNull("lastAttemptAt")&&!s.isNull("stale")&&!stamp(s.getString("fetchedAt")).isAfter(stamp(s.getString("lastAttemptAt"))),"主营成功时刻/状态缺失");need((has?"ready":"empty").equals(status)||status.equals("cached-after-failure"),"主营原数据与状态不符");need(Arrays.asList("host-fetch-response","fixture-constructed").contains(s.getString("origin")),"主营来源证据类型缺失");}
   else{need(s.isNull("fetchedAt")&&s.isNull("stale")&&s.isNull("origin")&&!s.getBoolean("cached"),"空资料被标为缓存成功");need(supported(id)?Arrays.asList("unavailable","failed").contains(status):status.equals("unsupported"),"空资料状态不符");}
   if(status.equals("failed")||status.equals("cached-after-failure"))need(s.opt("error") instanceof String&&!s.getString("error").isEmpty()&&s.getString("error").length()<=4096&&!s.isNull("lastAttemptAt"),"失败来源缺原因/请求时刻");else need(s.isNull("error"),"成功来源保留了未标记错误");
  }need(StockResearchModel.canonical(p).equals(StockResearchModel.canonical(derive(id,copy(sources)))),"主营派生字段与原来源不符");
 }
 static JSONObject cached(JSONObject packet,String at)throws Exception{String id=packet.getString("id");validate(id,packet);Instant now=stamp(at);JSONObject sources=copy(packet.getJSONObject("sources"));for(String kind:KINDS){JSONObject s=sources.getJSONObject(kind);if(!s.isNull("data")){Instant fetched=stamp(s.getString("fetchedAt"));need(!fetched.isAfter(now),"主营缓存时刻晚于本机检查时刻");s.put("cached",true).put("stale",!now.isBefore(fetched.plusMillis(TTL)));}}return derive(id,sources);}
 static JSONObject merge(String id,JSONObject responses,JSONObject previous,String checkedAt)throws Exception{StockResearchModel.identity(id);Instant now=stamp(checkedAt);if(previous!=null)validate(id,previous);JSONObject sources=previous==null?new JSONObject():cached(previous,checkedAt).getJSONObject("sources");for(String kind:KINDS){JSONObject s=sources.optJSONObject(kind);if(s==null)s=blank(id,kind);if(supported(id)&&responses.has(kind)){JSONObject reply=responses.getJSONObject(kind);String at=reply.getString("at");need(!stamp(at).isAfter(now),"来源响应时刻晚于检查时刻");try{need(reply.isNull("error")||!reply.has("error"),reply.optString("error","来源读取失败"));JSONObject data=reply.getJSONObject("body");boolean available=body(id,kind,data);String origin=reply.getString("origin");need(Arrays.asList("host-fetch-response","fixture-constructed").contains(origin),"资料来源证据类型无效");s=blank(id,kind).put("data",copy(data)).put("status",available?"ready":"empty").put("fetchedAt",at).put("lastAttemptAt",at).put("cached",false).put("stale",false).put("origin",origin);}catch(Exception e){String error=e.getMessage()==null?"来源读取失败":e.getMessage();need(error.length()<=4096,"来源失败原因超限");s.put("status",s.isNull("data")?"failed":"cached-after-failure").put("error",error).put("lastAttemptAt",at);}}sources.put(kind,s);}JSONObject result=derive(id,sources);validate(id,result);return result;}
 static String status(String s){switch(s){case "ready":return "已取得源数据";case "empty":return "来源返回空资料";case "failed":return "本次读取失败";case "cached-after-failure":return "读取失败，保留原缓存";case "unsupported":return "该证券类型未提供公司F10";default:return "尚未取得资料";}}
 static String overview(JSONObject p)throws Exception{validate(p.getString("id"),p);StringBuilder out=new StringBuilder("完整证券身份："+p.getString("id")+"\n来源证券简称："+StockResearchModel.display(p,"name")+"\n公司："+StockResearchModel.display(p,"companyName")+"\n行业："+StockResearchModel.display(p,"industry")+" · 证监行业："+StockResearchModel.display(p,"csrcIndustry")+"\n证券类型 / 交易市场（原来源字段）："+StockResearchModel.display(p,"securityType")+" / "+StockResearchModel.display(p,"exchange")+"\n经营回顾摘录："+StockResearchModel.display(p,"businessSummary")+"\n经营范围摘录："+StockResearchModel.display(p,"businessScope")+"\n\n主营组成（来源报告日）：\n");JSONArray items=p.getJSONArray("mainBusinessItems");if(items.length()==0)out.append("尚未提供主营组成\n");for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);out.append(item.getString("name")).append(" · ").append(item.isNull("ratio")?"占比未提供":String.format(Locale.ROOT,"%.2f%%",item.getDouble("ratio"))).append(" · 报告日：").append(StockResearchModel.display(item,"reportDate")).append('\n');}out.append("\n板块标签（来源）：");JSONArray boards=p.getJSONArray("boards");if(boards.length()==0)out.append("未提供");for(int i=0;i<boards.length();i++){if(i>0)out.append(" / ");out.append(boards.getString(i));}out.append('\n');for(String kind:KINDS){JSONObject s=p.getJSONObject("sources").getJSONObject(kind);out.append('\n').append(kind).append("：").append(status(s.getString("status"))).append("\n本机最后取得响应：").append(StockResearchModel.display(s,"fetchedAt")).append("\n最后读取尝试：").append(StockResearchModel.display(s,"lastAttemptAt")).append("\n本机缓存：").append(StockResearchModel.display(s,"cached")).append(" · 30天缓存过期：").append(StockResearchModel.display(s,"stale")).append("\n来源：").append(StockResearchModel.display(s,"url")).append('\n');if(!s.isNull("error"))out.append("失败原因：").append(s.getString("error")).append('\n');if("fixture-constructed".equals(s.optString("origin")))out.append("协议构造检查数据，非实际源响应\n");}return out.append("\n概览为源字段摘录；完整来源与原字段可在本页切换阅读。报告日、取得响应和保存时点分别保留。").toString();}
 static String original(JSONObject p,String kind)throws Exception{validate(p.getString("id"),p);need(Arrays.asList(KINDS).contains(kind),"请选择原主营来源");return "完整证券身份："+p.getString("id")+" · 原来源："+kind+"\n原来源完整字段与核对状态：\n"+p.getJSONObject("sources").getJSONObject(kind).toString(2);}
}
